mapper.select:
select cp.id, cp.club_id, cp.author_member_id, cp.content, cp.images, cp.ref_type, cp.ref_id, cp.type, cp.like_count, cp.comment_count, cp.del_flag, cp.is_pinned, cp.pinned_at, cp.version, cp.create_time, cp.update_time, exists(select 1 from club_post_revision r where r.post_id = cp.id) as edited, m.nickname as nickname, m.avatar as avatar from club_post cp join club c on c.id = cp.club_id and c.del_flag = 0 left join ums_member m on m.id = cp.author_member_id
cp.del_flag = 0 and cp.club_id = #{clubId} and cp.type = #{type}
order by cp.is_pinned desc, cp.pinned_at desc, cp.id desc

select cp.id, cp.club_id, cp.author_member_id, cp.content, cp.images, cp.ref_type, cp.ref_id, cp.type, cp.like_count, cp.comment_count, cp.del_flag, cp.is_pinned, cp.pinned_at, cp.version, cp.create_time, cp.update_time, exists(select 1 from club_post_revision r where r.post_id = cp.id) as edited, m.nickname as nickname, m.avatar as avatar from club_post cp join club c on c.id = cp.club_id and c.del_flag = 0 left join ums_member m on m.id = cp.author_member_id where cp.del_flag = 0 and cp.club_id = #{clubId}
and cp.is_pinned = 1 order by cp.pinned_at desc, cp.id desc
and cp.is_pinned = 0 and cp.id < #{beforeId} order by cp.id desc
limit #{limit}

mapper.update:
update club_post
content = #{content}, images = #{images}, like_count = #{likeCount}, comment_count = #{commentCount}, del_flag = #{delFlag}, update_time = now(), version = version + 1,
where id = #{id}

update club_post
set content = #{content}, images = #{images}, update_time = #{updateTime}, version = version + 1
where id = #{id} and del_flag = 0 and version = #{expectedVersion}

update club_post
set is_pinned = #{isPinned}, pinned_at = #{pinnedAt}, update_time = #{updateTime}, version = version + 1
where id = #{id} and del_flag = 0 and version = #{expectedVersion}
